"""Browsable photo-credit gallery for the offline Task 3 deliverable."""
from pathlib import Path
import html,json,re

ROOT=Path(__file__).resolve().parents[2]
TASK=ROOT/'交付文件'/'任务三_专题深挖'
MEDIA=TASK/'媒体'
items=json.loads((MEDIA/'图片来源与许可.json').read_text(encoding='utf-8'))
names={'host':'开幕与主场','lens':'统计口径','archive':'历史档案','islands':'小代表团','growth':'百年增长','portrait':'运动员肖像','dynasty':'冠军王朝','women':'女性参赛','museum':'消失的项目','sports':'当代赛场','la':'洛杉矶赛场'}
cards=[]
for i,x in enumerate(items,1):
    author=x.get('author') or '原页面未列出'
    license=x['license']
    cards.append(f'''<article class="photo-card" data-license="{html.escape(license)}"><div class="photo-frame"><img src="{html.escape(x['file'])}" alt="{html.escape(names.get(x['key'],x['title']))}的历史或比赛场景" loading="lazy"><span class="photo-number">{i:02d} / 11</span></div><div class="photo-body"><span class="category">{html.escape(names.get(x['key'],x['key']))}</span><h2>{html.escape(x['title'])}</h2><dl><div><dt>摄影 / 来源署名</dt><dd>{html.escape(author)}</dd></div><div><dt>许可</dt><dd>{html.escape(license)}</dd></div><div><dt>本地文件</dt><dd>{html.escape(x['file'])} · {x['width']} × {x['height']}</dd></div></dl><a href="{html.escape(x['source'],quote=True)}" target="_blank" rel="noopener">查看 Wikimedia Commons 原始页面 ↗</a></div></article>''')
page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>摄影来源与许可 · 百年圣火</title><style>
:root{{--ink:#142f35;--paper:#f1efe9;--line:#d7ddd6;--teal:#176d75}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--paper);color:var(--ink);font-family:'Microsoft YaHei',system-ui,sans-serif;line-height:1.6}}a{{color:inherit}}.top{{position:sticky;top:0;z-index:10;background:#102e37;color:#fff;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:12px clamp(20px,5vw,80px);box-shadow:0 6px 22px #102e3719}}.top a{{text-decoration:none}}.brand{{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:800}}.mark{{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:#a2d5c9;color:#183f44}}.top .back{{border:1px solid #ffffff55;padding:7px 12px;border-radius:8px;font-size:12px}}.hero{{padding:clamp(70px,9vw,125px) clamp(22px,6vw,95px) 65px;background:linear-gradient(105deg,#112d34f2,#143f46ad),url('sports.jpg') center/cover;color:#f7f6f0}}.hero small{{color:#e2b37e;letter-spacing:.2em;font-weight:900}}.hero h1{{font:600 clamp(44px,6vw,88px)/1.06 Georgia,'Songti SC',serif;letter-spacing:-.06em;margin:18px 0}}.hero p{{max-width:750px;font-size:17px;color:#e0e9e4}}main{{max-width:1400px;margin:auto;padding:58px clamp(20px,5vw,70px) 110px}}.intro{{display:flex;justify-content:space-between;gap:20px;align-items:end;border-bottom:1px solid #b8c9c4;padding-bottom:23px;margin-bottom:26px}}.intro h2{{font:600 clamp(31px,3.5vw,48px)/1.2 Georgia,'Songti SC',serif;margin:0}}.intro p{{margin:0;max-width:440px;color:#586e71;font-size:14px}}.toolbar{{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 26px}}.toolbar button{{font:700 13px 'Microsoft YaHei',sans-serif;border:1px solid #bdcec8;background:#fffdf9;color:#254c52;border-radius:999px;padding:9px 17px;cursor:pointer}}.toolbar button.active,.toolbar button:hover{{background:#164a52;color:#fff;border-color:#164a52}}.toolbar span{{margin-left:auto;color:#577075;font-size:12px}}.grid{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}}.photo-card{{background:#fffefa;border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:0 14px 32px #163a4010;transition:transform .25s,box-shadow .25s}}.photo-card:hover{{transform:translateY(-4px);box-shadow:0 22px 44px #163a4022}}.photo-card[hidden]{{display:none}}.photo-frame{{height:250px;position:relative;overflow:hidden;background:#dde7e2}}.photo-frame img{{width:100%;height:100%;object-fit:cover;transition:transform .7s}}.photo-card:hover img{{transform:scale(1.05)}}.photo-number{{position:absolute;top:14px;left:14px;background:#0a2731bd;color:#fff;border-radius:30px;padding:5px 10px;font:700 11px system-ui}}.photo-body{{padding:20px 22px 25px}}.category{{color:#a76f3d;font-size:11px;font-weight:900;letter-spacing:.12em}}.photo-body h2{{font:600 20px/1.28 Georgia,'Songti SC',serif;margin:9px 0 15px;min-height:50px;overflow-wrap:anywhere}}dl{{margin:0 0 18px}}dl div{{display:flex;justify-content:space-between;gap:14px;border-top:1px solid #e0e7e3;padding:7px 0;font-size:12px}}dt{{color:#6c7d7d;flex:0 0 92px}}dd{{margin:0;text-align:right;overflow-wrap:anywhere}}.photo-body a{{font-size:12px;font-weight:800;color:#116c78;text-underline-offset:3px}}.note{{background:#e2ebe6;border-left:3px solid #176d75;padding:17px 20px;margin:35px 0 0;color:#476468;font-size:13px}}footer{{background:#102e37;color:#d9e7e3;padding:26px clamp(20px,5vw,80px);display:flex;gap:20px;justify-content:space-between;font-size:12px}}footer a{{color:#fff}}@media(max-width:1000px){{.grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}@media(max-width:650px){{.intro{{display:block}}.intro p{{margin-top:10px}}.grid{{grid-template-columns:1fr}}.photo-frame{{height:240px}}.toolbar span{{width:100%;margin:4px 0 0}}footer{{display:block}}footer a{{display:block;margin-top:10px}}}}@media(prefers-reduced-motion:reduce){{*,*:before,*:after{{transition:none!important;animation:none!important}}}}
</style></head><body><div class="top"><a class="brand" href="../统一中文入口/index.html"><span class="mark">晓</span><span>奥运数据观察 / 摄影档案</span></a><a class="back" href="../统一中文入口/index.html">返回十专题 ↗</a></div><header class="hero"><small>VISUAL SOURCES / 01—11</small><h1>每一张照片，<br>都有出处。</h1><p>这里列出作品使用的 11 张本地照片、原始页面、作者和许可。照片帮助读者进入历史场景，不参与排名计算，也不充当统计结论的证据。</p></header><main><div class="intro"><h2>图像来源索引</h2><p>离线打开各专题时，图片从同目录读取。需核对许可细节时，请点击每张卡片的 Commons 原始页面。</p></div><div class="toolbar" role="group" aria-label="按许可筛选"><button class="active" data-filter="all" aria-pressed="true">全部照片</button><button data-filter="Public domain" aria-pressed="false">公有领域</button><button data-filter="CC0" aria-pressed="false">CC0</button><button data-filter="CC BY" aria-pressed="false">署名许可</button><span id="count" aria-live="polite">显示 11 张</span></div><section class="grid">{''.join(cards)}</section><div class="note">许可标记按来源页面记录；如需在作品以外重新使用照片，请再次核对 Commons 页面列出的具体版本、作者及署名要求。页面中的奥运数据另有独立的来源与使用条件。</div></main><footer><span>晓组织 · 奥运数据观察</span><a href="图片来源与许可.md" download="图片来源与许可.md">下载 Markdown 清单 ↓</a><a href="图片来源与许可.json" download="图片来源与许可.json">下载机器可读清单 ↓</a></footer><script>const buttons=document.querySelectorAll('[data-filter]'),cards=document.querySelectorAll('.photo-card'),count=document.querySelector('#count');buttons.forEach(b=>b.onclick=()=>{{const v=b.dataset.filter;buttons.forEach(x=>{{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))}});let n=0;cards.forEach(c=>{{const ok=v==='all'||c.dataset.license.includes(v);c.hidden=!ok;if(ok)n++}});count.textContent='显示 '+n+' 张'}});</script></body></html>'''
(MEDIA/'图片来源与许可.html').write_text(page,encoding='utf-8')
portal=TASK/'统一中文入口'/'index.html'
s=portal.read_text(encoding='utf-8')
s=s.replace('../媒体/图片来源与许可.md','../媒体/图片来源与许可.html')
s=s.replace('<a href="../十专题总览.md">专题清单与复现说明 ↗</a>','<a href="../十专题总览.html">专题清单与复现说明 ↗</a>')
s=s.replace('<a href="../十专题总览.md" download="十专题总览.md">下载专题清单与复现说明 ↓</a>','<a href="../十专题总览.html">专题清单与复现说明 ↗</a>')
portal.write_text(s,encoding='utf-8')
reference=TASK/'视觉设计参考.md'
if reference.exists():
 s=reference.read_text(encoding='utf-8').replace('媒体/图片来源与许可.md','媒体/图片来源与许可.html')
 reference.write_text(s,encoding='utf-8')
print(MEDIA/'图片来源与许可.html')
